?>

**5. Kompletny przykład strony:**

<?php
header('Content-Type: text/html; charset=UTF-8');
setlocale(LC_ALL, 'pl_PL.UTF-8');

$nazwa_uzytkownika = "Jaś Kowalski";
$komentarz = "Świetna strona! Mam pytanie: <skrypt>alert('test')</skrypt>";
